import numpy as np
import numba as nb


@nb.njit(cache=True)
def _lapjv(C):
    n = C.shape[0]
    INF = np.inf
    x = -np.ones(n, np.int64)   # col assigned to row
    y = -np.ones(n, np.int64)   # row assigned to col
    v = np.empty(n)
    # column reduction
    for j in range(n):
        v[j] = C[0, j]
        y[j] = 0
    for i in range(1, n):
        for j in range(n):
            if C[i, j] < v[j]:
                v[j] = C[i, j]
                y[j] = i
    matches = np.zeros(n, np.int64)
    for j in range(n - 1, -1, -1):
        i = y[j]
        matches[i] += 1
        if matches[i] == 1:
            x[i] = j
        else:
            y[j] = -1
    # reduction transfer
    free = np.empty(n, np.int64)
    nfree = 0
    for i in range(n):
        if matches[i] == 0:
            free[nfree] = i
            nfree += 1
        elif matches[i] == 1:
            j1 = x[i]
            mn = INF
            for j in range(n):
                if j != j1:
                    t = C[i, j] - v[j]
                    if t < mn:
                        mn = t
            v[j1] = v[j1] - (mn - (C[i, j1] - v[j1]))
            # standard: v[j1] -= min_{j!=j1}(C-v) - (C[i,j1]-v[j1])
    # augmenting row reduction (2 passes)
    for _ in range(2):
        k = 0
        prv = nfree
        nfree = 0
        while k < prv:
            i = free[k]
            k += 1
            u1 = C[i, 0] - v[0]
            j1 = 0
            u2 = INF
            j2 = -1
            for j in range(1, n):
                h = C[i, j] - v[j]
                if h < u2:
                    if h >= u1:
                        u2 = h
                        j2 = j
                    else:
                        u2 = u1
                        u1 = h
                        j2 = j1
                        j1 = j
            i0 = y[j1]
            if u1 < u2:
                v[j1] = v[j1] - (u2 - u1)
            elif i0 >= 0:
                j1 = j2
                i0 = y[j1]
            if i0 >= 0:
                if u1 < u2:
                    k -= 1
                    free[k] = i0
                else:
                    free[nfree] = i0
                    nfree += 1
            x[i] = j1
            y[j1] = i
    # augmentation (shortest path, dense)
    d = np.empty(n)
    pred = np.empty(n, np.int64)
    cols = np.empty(n, np.int64)
    for f in range(nfree):
        fi = free[f]
        for j in range(n):
            d[j] = C[fi, j] - v[j]
            pred[j] = fi
            cols[j] = j
        lo = 0
        up = 0
        last = 0
        endj = -1
        mn = 0.0
        while endj < 0:
            if lo == up:
                last = lo
                mn = d[cols[up]]
                up += 1
                for k in range(up, n):
                    j = cols[k]
                    h = d[j]
                    if h <= mn:
                        if h < mn:
                            up = lo
                            mn = h
                        cols[k] = cols[up]
                        cols[up] = j
                        up += 1
                for k in range(lo, up):
                    j = cols[k]
                    if y[j] < 0:
                        endj = j
                        break
            if endj < 0:
                j1 = cols[lo]
                lo += 1
                i = y[j1]
                u1 = C[i, j1] - v[j1] - mn
                for k in range(up, n):
                    j = cols[k]
                    h = C[i, j] - v[j] - u1
                    if h < d[j]:
                        d[j] = h
                        pred[j] = i
                        if h == mn:
                            if y[j] < 0:
                                endj = j
                                break
                            cols[k] = cols[up]
                            cols[up] = j
                            up += 1
        for k in range(last):
            j = cols[k]
            v[j] = v[j] + d[j] - mn
        j = endj
        while True:
            i = pred[j]
            y[j] = i
            k = j
            j = x[i]
            x[i] = k
            if i == fi:
                break
    return x


class Solver:
    def __init__(self):
        _lapjv(np.random.rand(5, 5))

    def solve(self, problem, **kwargs):
        a = np.asarray(problem["source_weights"], dtype=np.float64)
        b = np.asarray(problem["target_weights"], dtype=np.float64)
        M = np.ascontiguousarray(problem["cost_matrix"], dtype=np.float64)
        n, m = M.shape
        if n == m and n > 0 and np.all(a == a[0]) and np.all(b == a[0]):
            c = _lapjv(M)
            G = np.zeros((n, m))
            G[np.arange(n), c] = a[0]
            return {"transport_plan": G}
        import ot
        G = ot.lp.emd(a, b, M, check_marginals=False)
        return {"transport_plan": G}
