import numpy as np
import numba as nb


@nb.njit(cache=True)
def _topk_mask(M, k, mask):
    n, m = M.shape
    # rows
    buf = np.empty(k)
    for i in range(n):
        cnt = 0
        for j in range(m):
            c = M[i, j]
            if cnt < k:
                p = cnt
                cnt += 1
            elif c < buf[k - 1]:
                p = k - 1
            else:
                continue
            while p > 0 and buf[p - 1] > c:
                buf[p] = buf[p - 1]
                p -= 1
            buf[p] = c
        th = buf[k - 1]
        for j in range(m):
            if M[i, j] <= th:
                mask[i, j] = True
    # columns: per-column thresholds
    cb = np.empty((m, k))
    cc = np.zeros(m, np.int64)
    for i in range(n):
        for j in range(m):
            c = M[i, j]
            if cc[j] < k:
                p = cc[j]
                cc[j] += 1
            elif c < cb[j, k - 1]:
                p = k - 1
            else:
                continue
            while p > 0 and cb[j, p - 1] > c:
                cb[j, p] = cb[j, p - 1]
                p -= 1
            cb[j, p] = c
    for i in range(n):
        for j in range(m):
            if M[i, j] <= cb[j, k - 1]:
                mask[i, j] = True


@nb.njit(cache=True)
def _build(M, mask):
    n = M.shape[0]
    nnz = 0
    for i in range(n):
        for j in range(n):
            if mask[i, j]:
                nnz += 1
    indptr = np.zeros(n + 1, np.int64)
    indices = np.empty(nnz, np.int64)
    costs = np.empty(nnz)
    e = 0
    for i in range(n):
        for j in range(n):
            if mask[i, j]:
                indices[e] = j
                costs[e] = M[i, j]
                e += 1
        indptr[i + 1] = e
    return indptr, indices, costs


@nb.njit(cache=True)
def _sparse_lap(n, indptr, indices, costs):
    INF = np.inf
    v = np.full(n, INF)
    row4col = -np.ones(n, np.int64)
    col4row = -np.ones(n, np.int64)
    # column reduction
    for i in range(n):
        for e in range(indptr[i], indptr[i + 1]):
            j = indices[e]
            if costs[e] < v[j]:
                v[j] = costs[e]
    for j in range(n):
        if v[j] == INF:
            return col4row, v, False
    # greedy tight assignment
    for i in range(n):
        best = INF
        bj = -1
        for e in range(indptr[i], indptr[i + 1]):
            j = indices[e]
            r = costs[e] - v[j]
            if r < best:
                best = r
                bj = j
        if bj >= 0 and row4col[bj] < 0:
            row4col[bj] = i
            col4row[i] = bj
    dist = np.empty(n)
    pred = np.empty(n, np.int64)
    done = np.zeros(n, np.bool_)
    scanned = np.empty(n, np.int64)
    touched = np.empty(n, np.int64)
    hk = np.empty(indices.shape[0] + n + 1)
    hv = np.empty(indices.shape[0] + n + 1, np.int64)
    for j in range(n):
        dist[j] = INF
    for s in range(n):
        if col4row[s] >= 0:
            continue
        nt = 0
        ns = 0
        hs = 0
        base = INF
        for e in range(indptr[s], indptr[s + 1]):
            j = indices[e]
            r = costs[e] - v[j]
            if r < base:
                base = r
        for e in range(indptr[s], indptr[s + 1]):
            j = indices[e]
            d = costs[e] - v[j] - base
            if d < dist[j]:
                if dist[j] == INF:
                    touched[nt] = j
                    nt += 1
                dist[j] = d
                pred[j] = s
                p = hs
                hs += 1
                while p > 0:
                    q = (p - 1) >> 1
                    if hk[q] <= d:
                        break
                    hk[p] = hk[q]; hv[p] = hv[q]
                    p = q
                hk[p] = d; hv[p] = j
        sink = -1
        D = 0.0
        while hs > 0:
            d = hk[0]
            j = hv[0]
            hs -= 1
            if hs > 0:
                lk = hk[hs]; lv = hv[hs]
                p = 0
                while True:
                    c = 2 * p + 1
                    if c >= hs:
                        break
                    if c + 1 < hs and hk[c + 1] < hk[c]:
                        c += 1
                    if hk[c] >= lk:
                        break
                    hk[p] = hk[c]; hv[p] = hv[c]
                    p = c
                hk[p] = lk; hv[p] = lv
            if done[j] or d > dist[j]:
                continue
            done[j] = True
            scanned[ns] = j
            ns += 1
            i = row4col[j]
            if i < 0:
                sink = j
                D = d
                break
            ui = 0.0
            for e in range(indptr[i], indptr[i + 1]):
                if indices[e] == j:
                    ui = costs[e] - v[j]
                    break
