import numpy as np
import numba as nb


@nb.njit(cache=True)
def _build_csr(M, mask, nnz):
    n = M.shape[0]
    indptr = np.zeros(n + 1, np.int64)
    indices = np.empty(nnz, np.int64)
    costs = np.empty(nnz)
    e = 0
    for i in range(n):
        for j in range(n):
            if mask[i, j]:
                indices[e] = j
                costs[e] = M[i, j]
                e += 1
        indptr[i + 1] = e
    return indptr, indices, costs


@nb.njit(cache=True)
def _lap(n, indptr, indices, costs, x, y, v, mc, dist, pred, pc, done,
         scanned, touched, hk, hv):
    INF = np.inf
    for s in range(n):
        if x[s] >= 0:
            continue
        nt = 0
        ns = 0
        hs = 0
        base = INF
        for e in range(indptr[s], indptr[s + 1]):
            r = costs[e] - v[indices[e]]
            if r < base:
                base = r
        for e in range(indptr[s], indptr[s + 1]):
            j = indices[e]
            d = costs[e] - v[j] - base
            if d < dist[j]:
                if dist[j] == INF:
                    touched[nt] = j
                    nt += 1
                dist[j] = d
                pred[j] = s
                pc[j] = costs[e]
                p = hs
                hs += 1
                while p > 0:
                    q = (p - 1) >> 1
                    if hk[q] <= d:
                        break
                    hk[p] = hk[q]
                    hv[p] = hv[q]
                    p = q
                hk[p] = d
                hv[p] = j
        sink = -1
        D = 0.0
        while hs > 0:
            d = hk[0]
            j = hv[0]
            hs -= 1
            if hs > 0:
                lk = hk[hs]
                lv = hv[hs]
                p = 0
                while True:
                    c = 2 * p + 1
                    if c >= hs:
                        break
                    if c + 1 < hs and hk[c + 1] < hk[c]:
                        c += 1
                    if hk[c] >= lk:
                        break
                    hk[p] = hk[c]
                    hv[p] = hv[c]
                    p = c
                hk[p] = lk
                hv[p] = lv
            if done[j] or d > dist[j]:
                continue
            done[j] = True
            scanned[ns] = j
            ns += 1
            i = y[j]
            if i < 0:
                sink = j
                D = d
                break
            ui = mc[i] - v[j]
            for e in range(indptr[i], indptr[i + 1]):
                kk = indices[e]
                if done[kk]:
                    continue
                nd = d + costs[e] - v[kk] - ui
                if nd < dist[kk]:
                    if dist[kk] == INF:
                        touched[nt] = kk
                        nt += 1
                    dist[kk] = nd
                    pred[kk] = i
                    pc[kk] = costs[e]
                    p = hs
                    hs += 1
                    while p > 0:
                        q = (p - 1) >> 1
                        if hk[q] <= nd:
                            break
                        hk[p] = hk[q]
                        hv[p] = hv[q]
                        p = q
                    hk[p] = nd
                    hv[p] = kk
        if sink < 0:
            return False
        for t in range(ns):
            j = scanned[t]
            v[j] -= D - dist[j]
        j = sink
        while True:
            i = pred[j]
            y[j] = i
            pj = x[i]
            x[i] = j
            mc[i] = pc[j]
            if i == s:
                break
            j = pj
        for t in range(nt):
            kk = touched[t]
            dist[kk] = INF
            done[kk] = False
    return True


@nb.njit(cache=True)
def _assign(M, k):
    n = M.shape[0]
    INF = np.inf
    mask = np.zeros((n, n), np.bool_)
    buf = np.empty(k)
    for i in range(n):
        cnt = 0
        for j in range(n):
            c = M[i, j]
            if cnt < k:
                p = cnt
                cnt += 1
            elif c < buf[k - 1]:
                p = k - 1
            else:
                continue
            while p > 0 and buf[p - 1] > c:
                buf[p] = buf[p - 1]
                p -= 1
            buf[p] = c
        th = buf[k - 1]
        for j in range(n):
            if M[i, j] <= th:
                mask[i, j] = True
    cb = np.full((n, k), INF)
    for i in range(n):
        for j in range(n):
            c = M[i, j]
            if c < cb[j, k - 1]:
                p = k - 1
                while p > 0 and cb[j, p - 1] > c:
                    cb[j, p] = cb[j, p - 1]
                    p -= 1
                cb[j, p] = c
    nnz = 0
    for i in range(n):
        for j in range(n):
            if M[i, j] <= cb[j, k - 1]:
                mask[i, j] = True
            if mask[i, j]:
                nnz += 1
    indptr, indices, costs = _build_csr(M, mask, nnz)
    # initial duals: column minima over graph
    v = np.full(n, INF)
    for i in range(n):
        for e in range(indptr[i], indptr[i + 1]):
            j = indices[e]
            if costs[e] < v[j]:
                v[j] = costs[e]
    x = -np.ones(n, np.int64)
    y = -np.ones(n, np.int64)
    mc = np.zeros(n)
    for i in range(n):
        best = INF
        bj = -1
        bc = 0.0
        for e in range(indptr[i], indptr[i + 1]):
            j = indices[e]
            r = costs[e] - v[j]
            if r < best:
                best = r
                bj = j
                bc = costs[e]
        if y[bj] < 0:
            y[bj] = i
            x[i] = bj
            mc[i] = bc
    dist = np.full(n, INF)
    pred = np.empty(n, np.int64)
    pc = np.empty(n)
    done = np.zeros(n, np.bool_)
    scanned = np.empty(n, np.int64)
    touched = np.empty(n, np.int64)
    for outer in range(100):
        hk = np.empty(nnz + 1)
        hv = np.empty(nnz + 1, np.int64)
        ok = _lap(n, indptr, indices, costs, x, y, v, mc, dist, pred, pc,
                  done, scanned, touched, hk, hv)
        if not ok:
            return x, False
        nv = 0
        for i in range(n):
            ui = mc[i] - v[x[i]]
            bad = False
            for j in range(n):
                if M[i, j] - ui - v[j] < -1e-13:
                    if not mask[i, j]:
                        mask[i, j] = True
                        nnz += 1
                    bad = True
            if bad:
                nv += 1
                y[x[i]] = -1
                x[i] = -1
        if nv == 0:
            return x, True
        indptr, indices, costs = _build_csr(M, mask, nnz)
    return x, False


class Solver:
    def __init__(self):
        _assign(np.random.rand(6, 6), 3)

    def solve(self, problem, **kwargs):
        a = np.asarray(problem["source_weights"], dtype=np.float64)
        b = np.asarray(problem["target_weights"], dtype=np.float64)
        M = np.ascontiguousarray(problem["cost_matrix"], dtype=np.float64)
        n, m = M.shape
        if n == m and n > 1 and np.all(a == a[0]) and np.all(b == a[0]):
            c, ok = _assign(M, min(n, 12))
            if not ok:
                from scipy.optimize import linear_sum_assignment
                c = linear_sum_assignment(M)[1]
            G = np.zeros((n, m))
            G[np.arange(n), c] = a[0]
            return {"transport_plan": G}
        import ot
        G = ot.lp.emd(a, b, M, check_marginals=False)
        return {"transport_plan": G}
