import numpy as np
import numba as nb

INF = np.inf


@nb.njit(cache=True)
def _colmin(M):
    n = M.shape[0]
    v = M[0].copy()
    for i in range(1, n):
        for j in range(n):
            if M[i, j] < v[j]:
                v[j] = M[i, j]
    return v


@nb.njit(cache=True)
def _row_cands(M, v, i, k, mask):
    # mark k smallest reduced costs of row i
    n = M.shape[0]
    buf = np.empty(k)
    for j in range(k):
        c = M[i, j] - v[j]
        p = j
        while p > 0 and buf[p - 1] > c:
            buf[p] = buf[p - 1]
            p -= 1
        buf[p] = c
    th = buf[k - 1]
    for j in range(k, n):
        c = M[i, j] - v[j]
        if c < th:
            p = k - 1
            while p > 0 and buf[p - 1] > c:
                buf[p] = buf[p - 1]
                p -= 1
            buf[p] = c
            th = buf[k - 1]
    for j in range(n):
        if M[i, j] - v[j] <= th:
            mask[i, j] = True


@nb.njit(cache=True)
def _init_graph(M, v, k, tau, mask):
    n = M.shape[0]
    for i in range(n):
        cnt = 0
        for j in range(n):
            if M[i, j] - v[j] <= tau:
                mask[i, j] = True
                cnt += 1
        if cnt < k:
            _row_cands(M, v, i, k, mask)


@nb.njit(cache=True)
def _build_csr(M, mask):
    n = M.shape[0]
    nnz = 0
    for i in range(n):
        for j in range(n):
            if mask[i, j]:
                nnz += 1
    indptr = np.zeros(n + 1, np.int64)
    indices = np.empty(nnz, np.int64)
    costs = np.empty(nnz)
    e = 0
    for i in range(n):
        for j in range(n):
            if mask[i, j]:
                indices[e] = j
                costs[e] = M[i, j]
                e += 1
        indptr[i + 1] = e
    return indptr, indices, costs


@nb.njit(cache=True)
def _auction(n, indptr, indices, costs, v, x, y, eps0, epsf, sc, maxit):
    eps = eps0
    queue = np.empty(n, np.int64)
    it = 0
    while True:
        qn = 0
        for i in range(n):
            if x[i] < 0:
                queue[qn] = i
                qn += 1
        qh = 0
        while qn > 0:
            i = queue[qh]
            qh += 1
            if qh == n:
                qh = 0
            qn -= 1
            b1 = INF
            b2 = INF
            j1 = -1
            for e in range(indptr[i], indptr[i + 1]):
                j = indices[e]
                r = costs[e] - v[j]
                if r < b2:
                    if r < b1:
                        b2 = b1
                        b1 = r
                        j1 = j
                    else:
                        b2 = r
            if b2 == INF:
                b2 = b1 + 1.0
            v[j1] -= (b2 - b1) + eps
            o = y[j1]
            y[j1] = i
            x[i] = j1
            if o >= 0:
                x[o] = -1
                t = qh + qn
                if t >= n:
                    t -= n
                queue[t] = o
                qn += 1
            it += 1
            if it > maxit:
                return False
        if eps <= epsf:
            return True
        eps = max(eps * sc, epsf)
        for i in range(n):
            x[i] = -1
        for j in range(n):
            y[j] = -1


@nb.njit(cache=True)
def _lap(n, indptr, indices, costs, x, y, v, mc, dist, pred, pc, done,
         scanned, touched, hk, hv, reach):
    for s in range(n):
        if x[s] >= 0:
            continue
        nt = 0
        ns = 0
        hs = 0
        base = INF
        for e in range(indptr[s], indptr[s + 1]):
            r = costs[e] - v[indices[e]]
            if r < base:
                base = r
        for e in range(indptr[s], indptr[s + 1]):
            j = indices[e]
            d = costs[e] - v[j] - base
            if d < dist[j]:
                if dist[j] == INF:
                    touched[nt] = j
                    nt += 1
                dist[j] = d
                pred[j] = s
                pc[j] = costs[e]
                p = hs
                hs += 1
                while p > 0:
                    q = (p - 1) >> 1
                    if hk[q] <= d:
                        break
                    hk[p] = hk[q]
                    hv[p] = hv[q]
                    p = q
                hk[p] = d
                hv[p] = j
        sink = -1
        D = 0.0
        while hs > 0:
            d = hk[0]
            j = hv[0]
            hs -= 1
            if hs > 0:
                lk = hk[hs]
                lv = hv[hs]
                p = 0
                while True:
                    c = 2 * p + 1
                    if c >= hs:
                        break
                    if c + 1 < hs and hk[c + 1] < hk[c]:
                        c += 1
                    if hk[c] >= lk:
                        break
                    hk[p] = hk[c]
                    hv[p] = hv[c]
                    p = c
                hk[p] = lk
                hv[p] = lv
            if done[j] or d > dist[j]:
                continue
            done[j] = True
            scanned[ns] = j
            ns += 1
            i = y[j]
            if i < 0:
                sink = j
                D = d
                break
            ui = mc[i] - v[j]
            for e in range(indptr[i], indptr[i + 1]):
                kk = indices[e]
                if done[kk]:
                    continue
                nd = d + costs[e] - v[kk] - ui
                if nd < dist[kk]:
                    if dist[kk] == INF:
                        touched[nt] = kk
                        nt += 1
                    dist[kk] = nd
                    pred[kk] = i
                    pc[kk] = costs[e]
                    p = hs
                    hs += 1
                    while p > 0:
                        q = (p - 1) >> 1
                        if hk[q] <= nd:
                            break
                        hk[p] = hk[q]
                        hv[p] = hv[q]
                        p = q
                    hk[p] = nd
                    hv[p] = kk
        if sink < 0:
            nr = 1
            reach[0] = s
            for t in range(ns):
                r = y[scanned[t]]
                if r >= 0:
                    reach[nr] = r
                    nr += 1
            for t in range(nt):
                kk = touched[t]
                dist[kk] = INF
                done[kk] = False
            return nr
        for t in range(ns):
            j = scanned[t]
            v[j] -= D - dist[j]
        j = sink
        while True:
            i = pred[j]
            y[j] = i
            pj = x[i]
            x[i] = j
            mc[i] = pc[j]
            if i == s:
                break
            j = pj
        for t in range(nt):
            kk = touched[t]
            dist[kk] = INF
            done[kk] = False
    return 0


@nb.njit(cache=True)
def _check(M, x, v, mc, mask, bad):
    n = M.shape[0]
    nv = 0
    for i in range(n):
        ui = mc[i] - v[x[i]]
        b = False
        for j in range(n):
            if M[i, j] - ui - v[j] < -1e-13:
                mask[i, j] = True
                b = True
        bad[i] = b
        if b:
            nv += 1
    return nv


@nb.njit(cache=True)
def _assign(M, k, tau, e0, ef, sc):
    n = M.shape[0]
    v = _colmin(M)
    mask = np.zeros((n, n), np.bool_)
    _init_graph(M, v, k, tau, mask)
    indptr, indices, costs = _build_csr(M, mask)
    x = -np.ones(n, np.int64)
    y = -np.ones(n, np.int64)
    mc = np.zeros(n)
    xa = -np.ones(n, np.int64)
    ya = -np.ones(n, np.int64)
    va = v.copy()
    if e0 > 0 and _auction(n, indptr, indices, costs, va, xa, ya, e0, ef, sc, 100 * n):
        v[:] = va
        for i in range(n):
            j = xa[i]
            best = INF
            cij = 0.0
            for e in range(indptr[i], indptr[i + 1]):
                jj = indices[e]
                if jj == j:
                    cij = costs[e]
                else:
                    r = costs[e] - v[jj]
                    if r < best:
                        best = r
            r = cij - v[j]
            if r > best:
                v[j] += r - best
            x[i] = j
            y[j] = i
            mc[i] = cij
        # rows whose matched edge is no longer minimal become free
        for i in range(n):
            j = x[i]
            ui = mc[i] - v[j]
            for e in range(indptr[i], indptr[i + 1]):
                if costs[e] - v[indices[e]] < ui:
                    y[j] = -1
                    x[i] = -1
                    break
    else:
        for i in range(n):
            best = INF
            bj = -1
            bc = 0.0
            for e in range(indptr[i], indptr[i + 1]):
                j = indices[e]
                r = costs[e] - v[j]
                if r < best:
                    best = r
                    bj = j
                    bc = costs[e]
            if y[bj] < 0:
                y[bj] = i
                x[i] = bj
                mc[i] = bc
    dist = np.full(n, INF)
    pred = np.empty(n, np.int64)
    pc = np.empty(n)
    done = np.zeros(n, np.bool_)
    scanned = np.empty(n, np.int64)
    touched = np.empty(n, np.int64)
    reach = np.empty(n + 1, np.int64)
    bad = np.zeros(n, np.bool_)
    for outer in range(4 * n + 10):
        nnz = indices.shape[0]
        hk = np.empty(nnz + 1)
        hv = np.empty(nnz + 1, np.int64)
        nr = _lap(n, indptr, indices, costs, x, y, v, mc, dist, pred, pc,
                  done, scanned, touched, hk, hv, reach)
        if nr > 0:
            kk2 = min(n, 2 * k)
            for t in range(nr):
                _row_cands(M, v, reach[t], kk2, mask)
            k = kk2
            indptr, indices, costs = _build_csr(M, mask)
            continue
        nv = _check(M, x, v, mc, mask, bad)
        if nv == 0:
            return x, True
        for i in range(n):
            if bad[i]:
                y[x[i]] = -1
                x[i] = -1
        indptr, indices, costs = _build_csr(M, mask)
    return x, False


PARAMS = (10, 0.0, 0.05, 1e-3, 0.1)


class Solver:
    def __init__(self):
        _assign(np.random.rand(30, 30), 4, 0.0, 0.05, 1e-3, 0.1)

    def solve(self, problem, **kwargs):
        a = np.asarray(problem["source_weights"], dtype=np.float64)
        b = np.asarray(problem["target_weights"], dtype=np.float64)
        M = np.ascontiguousarray(problem["cost_matrix"], dtype=np.float64)
        n, m = M.shape
        if n == m and n > 1 and np.all(a == a[0]) and np.all(b == a[0]):
            k, tau, e0, ef, sc = PARAMS
            cm = float(M.max()) if False else 1.0
            c, ok = _assign(M, min(n, k), tau, e0 * cm, ef * cm, sc)
            if not ok:
                from scipy.optimize import linear_sum_assignment
                c = linear_sum_assignment(M)[1]
            G = np.zeros((n, m))
            G[np.arange(n), c] = a[0]
            return {"transport_plan": G}
        import ot
        G = ot.lp.emd(a, b, M, check_marginals=False)
        return {"transport_plan": G}
