            if C[i, j] < v[j]:
                v[j] = C[i, j]; y[j] = i
    matches = np.zeros(n, np.int64)
    for j in range(n - 1, -1, -1):
        i = y[j]
        matches[i] += 1
        if matches[i] == 1:
            x[i] = j
        else:
            y[j] = -1
    free = np.empty(n, np.int64); nfree = 0
    for i in range(n):
