                    j = cols[k]; h = d[j]
                    if h <= mn:
                        if h < mn:
                            up = lo; mn = h
                        cols[k] = cols[up]; cols[up] = j; up += 1
                for k in range(lo, up):
                    j = cols[k]
                    if y[j] < 0:
                        endj = j; break
            if endj < 0:
                j1 = cols[lo]; lo += 1
                i = y[j1]
                u1 = C[i, j1] - v[j1] - mn
                for k in range(up, n):
                    j = cols[k]
                    h = C[i, j] - v[j] - u1
                    if h < d[j]:
                        d[j] = h; pred[j] = i
                        if h == mn:
                            if y[j] < 0:
                                endj = j; break
                            cols[k] = cols[up]; cols[up] = j; up += 1
        for k in range(last):
            j = cols[k]
            v[j] += d[j] - mn
        j = endj
        while True:
            i = pred[j]; y[j] = i
            k = j; j = x[i]; x[i] = k
            if i == fi: break
    return x, nfree, steps
